import json,re
from collections import Counter
manifest='/mnt/data/LSF/baseline_results/court/agentic_codex_qa_gpt54_all/first_10_queries/q08/logs/q08.manifest.json'
with open(manifest) as f:
    m=json.load(f)
role_pat = re.compile(r'(Chief Judge|Senior Circuit Judge|Circuit Judges?|Circuit Judge|Senior District Judge|District Judges?|District Judge|Magistrate Judge|Bankruptcy Judge|Chief Justice|Justices?|Justice)\\.?', re.I)
role_end_pat = re.compile(r'(Chief Judge|Senior Circuit Judge|Circuit Judges?|Circuit Judge|Senior District Judge|District Judges?|District Judge|Magistrate Judge|Bankruptcy Judge|Chief Justice|Justices?|Justice)\\.?\\s*\\**\\s*"'$'"', re.I)
section_pat = re.compile(r'"'^(Opinion by|Concurrence by|Dissent by|Partial Concurrence|Partial Dissent|Statement by|Order;|Order$|SUMMARY'"\\*?|COUNSEL|OPINION|MEMORANDUM|Appeal from|Argued and Submitted|Submitted|FILED|PER CURIAM)', re.I)

def split_names(seg):
    seg=seg.strip()
    seg=re.sub(r'"'^[,;'"\\s]+', '', seg)
    seg=re.sub(r'"'^(and|&)'"\\s+', '', seg)
    seg=re.sub(r'[,:;\\s]+"'$'"', '', seg)
    if not seg:
        return []
    seg=re.sub(r',\\s+(Jr\\.|Sr\\.|II|III|IV)\\b', r' @@\\1', seg)
    parts=re.split(r',\\s*|\\s+and\\s+', seg)
    out=[]
    for p in parts:
        p=p.replace('@@', ', ')
        p=re.sub(r'\\s+', ' ', p).strip(' ,.;')
        if p:
            out.append(p)
    return out

def format_names(names):
    if not names:
        return None
    if len(names)==1:
        return names[0]
    if len(names)==2:
        return f'{names[0]} and {names[1]}'
    return ', '.join(names[:-1]) + ', and ' + names[-1]

def extract(path):
    text=open(path, errors='ignore').read().replace('\\f','\\n')
    lines=[ln.strip() for ln in text.splitlines()]
    raw=None
    for i,line in enumerate(lines):
        m=re.match(r'"'^(Before|BEFORE):'"\\s*(.*)"'$'"', line)
        if not m:
            continue
        first=m.group(2).strip()
        if 'En Banc Coordinator' in first:
            return None, 'en_banc_coord'
        block=[]
        if first:
            block.append(first)
        if role_end_pat.search(first):
            raw=' '.join(block)
            break
        for j in range(i+1, min(i+8, len(lines))):
            s=lines[j]
            if not s:
                if block:
                    break
                continue
            if section_pat.match(s):
                break
            block.append(s)
            if role_end_pat.search(s):
                break
        raw=' '.join(block).strip()
        break
    if not raw:
        return None, 'no_before'
    if 'En Banc Coordinator' in raw:
        return None, 'en_banc_coord'
    raw=raw.replace('*',' ')
    pieces=[]
    last=0
    for m in role_pat.finditer(raw):
        seg=raw[last:m.start()]
        pieces.extend(split_names(seg))
        last=m.end()
    if not pieces:
        return None, 'no_pieces'
    # dedupe consecutive accidental duplicates
    names=[]
    for p in pieces:
        if not names or names[-1]"'!=p:
